@dataclasses.dataclass
class Pose:
    """Fast class: attitude [omega, q] and position [V, P], full precision."""
    PORT: ClassVar[Optional[int]] = 0x80
    IS_HEARTBEAT: ClassVar[bool] = False
    QOS: ClassVar[int] = 3  # telemetry
    LATEST: ClassVar[bool] = True
    AIR_ELIGIBLE: ClassVar[bool] = False
    AIR_RATE_HZ: ClassVar[int] = 0
    USB_RATE_HZ: ClassVar[int] = 100
    MAX_SIZE: ClassVar[int] = 56
    MIN_SIZE: ClassVar[int] = 56
    t_us: int = 0  # [us] 
    omega: list[float] = dataclasses.field(default_factory=lambda: [0.0] * 3)  # [rad/s] body rates
    q: list[float] = dataclasses.field(default_factory=lambda: [0.0] * 4)  # [w,x,y,z] body -> world
    vel: list[float] = dataclasses.field(default_factory=lambda: [0.0] * 3)  # [m/s] NWU
    pos: list[float] = dataclasses.field(default_factory=lambda: [0.0] * 3)  # [m] NWU from the reset reference

    def encode(self) -> bytes:
        """Wire bytes. Raises ValueError on out-of-range integers or wrong array lengths."""
        b = bytearray(56)
        _rt.put(b, '<I', 0, self.t_us)
        if len(self.omega) != 3:
            raise ValueError('omega needs 3 elements')
        for i, v in enumerate(self.omega):
            _rt.put_f32(b, 4 + i * 4, v)
        if len(self.q) != 4:
            raise ValueError('q needs 4 elements')
        for i, v in enumerate(self.q):
            _rt.put_f32(b, 16 + i * 4, v)
        if len(self.vel) != 3:
            raise ValueError('vel needs 3 elements')
        for i, v in enumerate(self.vel):
            _rt.put_f32(b, 32 + i * 4, v)
        if len(self.pos) != 3:
            raise ValueError('pos needs 3 elements')
        for i, v in enumerate(self.pos):
            _rt.put_f32(b, 44 + i * 4, v)
        return bytes(b)

    @classmethod
    def decode(cls, data) -> "Pose":
        """Raises ValueError if shorter than MIN_SIZE. Longer input is accepted, extra bytes ignored."""
        data = bytes(data)
        if len(data) < cls.MIN_SIZE:
            raise ValueError('POSE: payload too short (%d < 56)' % len(data))
        t = cls()
        t.t_us = _rt.get(data, '<I', 0)
        t.omega = [_rt.get(data, '<f', 4 + i * 4) for i in range(3)]
        t.q = [_rt.get(data, '<f', 16 + i * 4) for i in range(4)]
        t.vel = [_rt.get(data, '<f', 32 + i * 4) for i in range(3)]
        t.pos = [_rt.get(data, '<f', 44 + i * 4) for i in range(3)]
        return t


@dataclasses.dataclass
class Actuators:
    """Actuator outputs."""
    PORT: ClassVar[Optional[int]] = 0x81
    IS_HEARTBEAT: ClassVar[bool] = False
    QOS: ClassVar[int] = 3  # telemetry
    LATEST: ClassVar[bool] = True
    AIR_ELIGIBLE: ClassVar[bool] = False
    AIR_RATE_HZ: ClassVar[int] = 0
    USB_RATE_HZ: ClassVar[int] = 50
    MAX_SIZE: ClassVar[int] = 40
    MIN_SIZE: ClassVar[int] = 36
    t_us: int = 0  # [us] 
    flaps: list[float] = dataclasses.field(default_factory=lambda: [0.0] * 4)  # [rad] [TL, TR, BL, BR]; 0 = extended, increasing = folded toward the back
    tvc: list[float] = dataclasses.field(default_factory=lambda: [0.0] * 2)  # [rad] thrust vector deflection [x, y]
    thrust: float = 0.0  # [N] 
    ground_distance: float = 0.0  # [m] NaN if unavailable
    roll_torque: float = 0.0  # [N*m] TVC twist (roll) actuation as the roll torque about body Z the vanes produce (same meaning as AIR_ACTUATORS.roll_torque, unquantised). Missing (older sender) decodes as NaN = unknown

    def encode(self) -> bytes:
        """Wire bytes. Raises ValueError on out-of-range integers or wrong array lengths."""
        b = bytearray(40)
        _rt.put(b, '<I', 0, self.t_us)
        if len(self.flaps) != 4:
            raise ValueError('flaps needs 4 elements')
        for i, v in enumerate(self.flaps):
            _rt.put_f32(b, 4 + i * 4, v)
        if len(self.tvc) != 2:
            raise ValueError('tvc needs 2 elements')
        for i, v in enumerate(self.tvc):
            _rt.put_f32(b, 20 + i * 4, v)
        _rt.put_f32(b, 28, self.thrust)
        _rt.put_f32(b, 32, self.ground_distance)
        _rt.put_f32(b, 36, self.roll_torque)
        return bytes(b)

    @classmethod
    def decode(cls, data) -> "Actuators":
        """Raises ValueError if shorter than MIN_SIZE. Longer input is accepted, extra bytes ignored."""
        data = bytes(data)
        if len(data) < cls.MIN_SIZE:
            raise ValueError('ACTUATORS: payload too short (%d < 36)' % len(data))
        t = cls()
        t.t_us = _rt.get(data, '<I', 0)
        t.flaps = [_rt.get(data, '<f', 4 + i * 4) for i in range(4)]
        t.tvc = [_rt.get(data, '<f', 20 + i * 4) for i in range(2)]
        t.thrust = _rt.get(data, '<f', 28)
        t.ground_distance = _rt.get(data, '<f', 32)
        if len(data) >= 40:
            t.roll_torque = _rt.get(data, '<f', 36)
        else:
            t.roll_torque = float('nan')
        return t


@dataclasses.dataclass
class Mission:
    """Mission setpoints and progress."""
    PORT: ClassVar[Optional[int]] = 0x82
    IS_HEARTBEAT: ClassVar[bool] = False
    QOS: ClassVar[int] = 3  # telemetry
    LATEST: ClassVar[bool] = True
    AIR_ELIGIBLE: ClassVar[bool] = False
    AIR_RATE_HZ: ClassVar[int] = 0
    USB_RATE_HZ: ClassVar[int] = 20
    MAX_SIZE: ClassVar[int] = 52
    MIN_SIZE: ClassVar[int] = 34
    t_us: int = 0  # [us] 
    setpoint_pos: list[float] = dataclasses.field(default_factory=lambda: [0.0] * 3)  # [m] 
    setpoint_vel: list[float] = dataclasses.field(default_factory=lambda: [0.0] * 3)  # [m/s] 
    mission_time: float = 0.0  # [s] 
    index: int = 0
    phase: int = 0
    setpoint_q: list[float] = dataclasses.field(default_factory=lambda: [0.0] * 4)  # attitude setpoint of the active attitude controller, [w,x,y,z] body -> world, NWU (as POSE.q). All four 0 = no attitude setpoint (no attitude controller active), otherwise a unit quaternion. NaN (missing, older sender) = unknown, treat as no setpoint
    mission_mode: int = 0  # MissionMode of the active mission (Idle, Initialisation, Startup, Running, Finished), as AIR_MISSION.mission_mode and VEHICLE_STATUS.mission_mode. Missing (older sender) decodes as 0
    waypoint: int = 0  # current waypoint index, 255 = the active mission is not the waypoint mission (as AIR_MISSION.waypoint). Missing (older sender) decodes as 0, so use mission_mode/VEHICLE_STATUS to know the sender is new

    def encode(self) -> bytes:
        """Wire bytes. Raises ValueError on out-of-range integers or wrong array lengths."""
        b = bytearray(52)
        _rt.put(b, '<I', 0, self.t_us)
        if len(self.setpoint_pos) != 3:
            raise ValueError('setpoint_pos needs 3 elements')
        for i, v in enumerate(self.setpoint_pos):
            _rt.put_f32(b, 4 + i * 4, v)
        if len(self.setpoint_vel) != 3:
            raise ValueError('setpoint_vel needs 3 elements')
        for i, v in enumerate(self.setpoint_vel):
            _rt.put_f32(b, 16 + i * 4, v)
        _rt.put_fixed(b, '<i', 28, self.mission_time, 0.001, -2147483647, 2147483647, -2147483648)
        _rt.put(b, '<B', 32, self.index)
        _rt.put(b, '<B', 33, self.phase)
        if len(self.setpoint_q) != 4:
            raise ValueError('setpoint_q needs 4 elements')
        for i, v in enumerate(self.setpoint_q):
            _rt.put_f32(b, 34 + i * 4, v)
        _rt.put(b, '<B', 50, self.mission_mode)
        _rt.put(b, '<B', 51, self.waypoint)
        return bytes(b)

    @classmethod
    def decode(cls, data) -> "Mission":
        """Raises ValueError if shorter than MIN_SIZE. Longer input is accepted, extra bytes ignored."""
        data = bytes(data)
        if len(data) < cls.MIN_SIZE:
            raise ValueError('MISSION: payload too short (%d < 34)' % len(data))
        t = cls()
        t.t_us = _rt.get(data, '<I', 0)
        t.setpoint_pos = [_rt.get(data, '<f', 4 + i * 4) for i in range(3)]
        t.setpoint_vel = [_rt.get(data, '<f', 16 + i * 4) for i in range(3)]
        t.mission_time = _rt.get_fixed(data, '<i', 28, 0.001, -2147483648)
        t.index = _rt.get(data, '<B', 32)
        t.phase = _rt.get(data, '<B', 33)
        if len(data) >= 50:
            t.setpoint_q = [_rt.get(data, '<f', 34 + i * 4) for i in range(4)]
        else:
            t.setpoint_q = [float('nan')] * 4
        if len(data) >= 51:
            t.mission_mode = _rt.get(data, '<B', 50)
        else:
            t.mission_mode = 0
        if len(data) >= 52:
            t.waypoint = _rt.get(data, '<B', 51)
        else:
            t.waypoint = 0
        return t


@dataclasses.dataclass
class RcApplied:
    """T9b, USB only (no air cost): the RC_STATE switch positions as the vehicle decodes them (channel table, flight-software docs), the transition detectors' safe-seen bits, the age of both control sources and the RC_STATE reject counters. For bench debugging of the Pocket mapping."""
    PORT: ClassVar[Optional[int]] = 0x84
    IS_HEARTBEAT: ClassVar[bool] = False
    QOS: ClassVar[int] = 3  # telemetry
    LATEST: ClassVar[bool] = True
    AIR_ELIGIBLE: ClassVar[bool] = False
    AIR_RATE_HZ: ClassVar[int] = 0
    USB_RATE_HZ: ClassVar[int] = 10
    MAX_SIZE: ClassVar[int] = 18
    MIN_SIZE: ClassVar[int] = 18
    SAFE_SEEN_GO: ClassVar[int] = 1
    SAFE_SEEN_SC_REAL: ClassVar[int] = 2
    SAFE_SEEN_SD_ENABLE: ClassVar[int] = 4
    SAFE_SEEN_SE_PRESS: ClassVar[int] = 8
    t_us: int = 0  # [us] 
    sa: int = 0  # SA decoded: 0 NOT_GO, 1 GO (invalid decodes to 0)
    sb: int = 0  # SB decoded: 0, 1, 2, 255 = invalid
    sc: int = 0  # SC decoded: 0 sim, 1 real, 2 reserved, 255 = invalid
    sd: int = 0  # SD decoded: 0 DISABLED, 1 ENABLED (invalid decodes to 0)
    se: int = 0  # SE decoded: 0 RELEASED, 1 PRESSED (invalid decodes to 0)
    safe_seen: int = 0  # each unsafe-direction detector's 'safe value seen' bit (set: an edge may be reported). Bits 4..7 reserved
    radio_age: float = 0.0  # [s] age of the last accepted RC_STATE from the RADIO source, invalid (NaN) = none
    bench_age: float = 0.0  # [s] age of the last accepted RC_STATE from the USB (bench) source, invalid (NaN) = none
    rejects: list[int] = dataclasses.field(default_factory=lambda: [0] * 4)  # wrapping reject counters per reason: [0] bad length or undecodable, [1] source (src, link) not in the table, [2] stale or repeated sequence, [3] SOURCE_OK clear

    def encode(self) -> bytes:
        """Wire bytes. Raises ValueError on out-of-range integers or wrong array lengths."""
        b = bytearray(18)
        _rt.put(b, '<I', 0, self.t_us)
        _rt.put(b, '<B', 4, self.sa)
        _rt.put(b, '<B', 5, self.sb)
        _rt.put(b, '<B', 6, self.sc)
        _rt.put(b, '<B', 7, self.sd)
        _rt.put(b, '<B', 8, self.se)
        _rt.put(b, '<B', 9, self.safe_seen)
        _rt.put_fixed(b, '<H', 10, self.radio_age, 0.001, 0, 65534, 65535)
        _rt.put_fixed(b, '<H', 12, self.bench_age, 0.001, 0, 65534, 65535)
        if len(self.rejects) != 4:
            raise ValueError('rejects needs 4 elements')
        for i, v in enumerate(self.rejects):
            _rt.put(b, '<B', 14 + i * 1, v)
        return bytes(b)

    @classmethod
    def decode(cls, data) -> "RcApplied":
        """Raises ValueError if shorter than MIN_SIZE. Longer input is accepted, extra bytes ignored."""
        data = bytes(data)
        if len(data) < cls.MIN_SIZE:
            raise ValueError('RC_APPLIED: payload too short (%d < 18)' % len(data))
        t = cls()
        t.t_us = _rt.get(data, '<I', 0)
        t.sa = _rt.get(data, '<B', 4)
        t.sb = _rt.get(data, '<B', 5)
        t.sc = _rt.get(data, '<B', 6)
        t.sd = _rt.get(data, '<B', 7)
        t.se = _rt.get(data, '<B', 8)
        t.safe_seen = _rt.get(data, '<B', 9)
        t.radio_age = _rt.get_fixed(data, '<H', 10, 0.001, 65535)
        t.bench_age = _rt.get_fixed(data, '<H', 12, 0.001, 65535)
        t.rejects = [_rt.get(data, '<B', 14 + i * 1) for i in range(4)]
        return t


@dataclasses.dataclass
class Gnss:
    """GNSS solution at 10 Hz (the latest receiver solution; 5 Hz before 2026-11-21). Latitude and longitude in radians as f64 (full receiver resolution, 1e-7 degree is about 1 cm), altitude in metres as the receiver driver reports it (the u-blox height above the WGS-84 ellipsoid, not above mean sea level: it differs from the barometric altitude by the geoid separation, so compare changes or values relative to the pad, not absolute values). Used to verify the barometric/estimated altitude during descent; AIR_GNSS is the compact version for the radio."""
    PORT: ClassVar[Optional[int]] = 0x83
    IS_HEARTBEAT: ClassVar[bool] = False
    QOS: ClassVar[int] = 3  # telemetry
    LATEST: ClassVar[bool] = True
