    USB_RATE_HZ: ClassVar[int] = 10
    MAX_SIZE: ClassVar[int] = 50
    MIN_SIZE: ClassVar[int] = 50
    t_us: int = 0  # [us] 
    latitude: float = 0.0  # [rad] 
    longitude: float = 0.0  # [rad] 
    altitude: float = 0.0  # [m] 
    vel: list[float] = dataclasses.field(default_factory=lambda: [0.0] * 3)  # [m/s] NWU
    satellites: int = 0
    fix_type: int = 0
    h_acc: float = 0.0  # [m] 
    v_acc: float = 0.0  # [m] 
    s_acc: float = 0.0  # [m/s] 

    def encode(self) -> bytes:
        """Wire bytes. Raises ValueError on out-of-range integers or wrong array lengths."""
        b = bytearray(50)
        _rt.put(b, '<I', 0, self.t_us)
        _rt.put_f64(b, 4, self.latitude)
        _rt.put_f64(b, 12, self.longitude)
        _rt.put_f32(b, 20, self.altitude)
        if len(self.vel) != 3:
            raise ValueError('vel needs 3 elements')
        for i, v in enumerate(self.vel):
            _rt.put_f32(b, 24 + i * 4, v)
        _rt.put(b, '<B', 36, self.satellites)
        _rt.put(b, '<B', 37, self.fix_type)
        _rt.put_f32(b, 38, self.h_acc)
        _rt.put_f32(b, 42, self.v_acc)
        _rt.put_f32(b, 46, self.s_acc)
        return bytes(b)

    @classmethod
    def decode(cls, data) -> "Gnss":
        """Raises ValueError if shorter than MIN_SIZE. Longer input is accepted, extra bytes ignored."""
        data = bytes(data)
        if len(data) < cls.MIN_SIZE:
            raise ValueError('GNSS: payload too short (%d < 50)' % len(data))
        t = cls()
        t.t_us = _rt.get(data, '<I', 0)
        t.latitude = _rt.get(data, '<d', 4)
        t.longitude = _rt.get(data, '<d', 12)
        t.altitude = _rt.get(data, '<f', 20)
        t.vel = [_rt.get(data, '<f', 24 + i * 4) for i in range(3)]
        t.satellites = _rt.get(data, '<B', 36)
        t.fix_type = _rt.get(data, '<B', 37)
        t.h_acc = _rt.get(data, '<f', 38)
        t.v_acc = _rt.get(data, '<f', 42)
        t.s_acc = _rt.get(data, '<f', 46)
        return t


